native_final_expiry.text:
CsrHopLayer::CheckResend ()
{
  if (m_resendQueue.empty ())
    {
      return;
    }

  Time now = Simulator::Now ();

  for (auto it = m_resendQueue.begin (); it != m_resendQueue.end (); /* no increment */)
    {
      ResendEntry &e = *it;

      // An OPNET resend entry starts with A_VERY_LARGE_NUMBER and cannot
      // expire until MAC reports the first real transmission instant.
      if (!e.initialTxConfirmed)
        {
          ++it;
          continue;
        }

      if (e.resendCount >= m_maxNumResend)
        {
          // Legacy br_hop waits 2 * RESEND_TIME after the
          // final retransmission before declaring the packet
          // unacknowledged. This gives a delayed ACK one last
          // chance to arrive.
          Time finalAckWait =
            m_resendTime +
            m_resendTime;

          Time sinceLastTx =
            now -
            e.lastTxTime;

          if (sinceLastTx <
              finalAckWait)
            {
              std::cout << "[HOP " << m_nodeId
                        << "] Waiting final ACK grace"
                        << " dest=" << e.dest
                        << " seq=" << e.seq
                        << " resendCount="
                        << e.resendCount
                        << " elapsedSec="
                        << sinceLastTx.GetSeconds ()
                        << " requiredSec="
                        << finalAckWait.GetSeconds ()
                        << std::endl;

              ++it;
              continue;
            }

          NS_LOG_INFO ("Hop " << m_nodeId
                              << " giving up on dest="
                              << e.dest
                              << " seq=" << e.seq);

          // Legacy HOP reports a final failure to NWK only when the resend
          // packet carries Packet_Tx_Info.  In this model that metadata is
          // represented by reliable KeyUpdate, NeighborCheck, and
          // ROUTING_CONTROL frames.  Ordinary DATA has no Packet_Tx_Info and
          // therefore must not be converted into a routing-link failure
          // merely because its resend limit expired.
          if (e.frame != nullptr)
            {
              Ptr<Packet> failedFrame =
                e.frame->Copy ();

              CsrHeader failedHopHeader;

              if (failedFrame->RemoveHeader (failedHopHeader))
                {
                  if (failedHopHeader.GetType () == CSR_PKT_KEY_UPDATE)
                    {
                      std::cout << "[HOP " << m_nodeId
                                << "] Reliable KeyUpdate FAILED"
                                << " neighbor=" << e.dest
                                << std::endl;

                      m_hopSecurity.MarkKeyUpdateFailed (e.dest);

                      if (!m_keyUpdateCompletionCb.IsNull ())
                        {
                          m_keyUpdateCompletionCb (e.dest, false);
                        }
                    }
                  else if (failedHopHeader.GetType () ==
                           CSR_PKT_NEIGHBOR_CHECK)
                    {
                      bool haveMetadata =
                        e.neighborCheckMetadataValid;
                      CsrNeighborCheckType checkType =
                        e.neighborCheckType;
                      uint32_t discoverySequence =
                        e.neighborCheckDiscoverySequence;

                      if (!haveMetadata &&
                          !failedHopHeader.HasSecurityCount ())
                        {
                          CsrHelloHeader controlHeader;
                          if (failedFrame->RemoveHeader (controlHeader))
                            {
                              haveMetadata = true;
                              checkType =
                                controlHeader.GetNeighborCheckType ();
                              discoverySequence =
                                controlHeader.GetDiscoverySequence ();
                            }
                        }

                      if (haveMetadata &&
                          !m_neighborCheckFailureCb.IsNull ())
                        {
                          m_neighborCheckFailureCb (
                            e.dest,
                            checkType,
                            discoverySequence);
                        }
                    }
                  else if (failedHopHeader.GetType () ==
                           CSR_PKT_ROUTING_CONTROL)
                    {
                      bool haveMetadata = e.routingMetadataValid;
                      uint32_t routingSequence = e.routingSequence;
                      CsrRoutingOperation operation = e.routingOperation;
                      uint8_t routingSection = e.routingSection;
                      uint8_t routingTotalSections =
                        e.routingTotalSections;

                      if (!haveMetadata &&
                          !failedHopHeader.HasGroupSecurity ())
                        {
                          CsrHelloHeader controlHeader;
                          if (failedFrame->RemoveHeader (controlHeader))
                            {
                              haveMetadata = true;
                              routingSequence =
                                controlHeader.GetRoutingSequence ();
                              operation =
                                controlHeader.GetRoutingOperation ();
                              routingSection =
                                controlHeader.GetRoutingSection ();
                              routingTotalSections =
                                controlHeader.GetRoutingTotalSections ();
                            }
                        }

                      if (haveMetadata)
                        {
                          std::cout << "[HOP " << m_nodeId
                                    << "] Reliable RoutingControl FAILED"
                                    << " neighbor=" << e.dest
                                    << " routingSequence=" << routingSequence
                                    << " operation="
                                    << unsigned (static_cast<uint8_t> (operation))
                                    << " section="
                                    << unsigned (routingSection)
                                    << "/"
                                    << unsigned (routingTotalSections)
                                    << std::endl;

                          if (!m_routingControlFailureCb.IsNull ())
                            {
                              std::vector<CsrNodeId> failedDestinations;
                              failedDestinations.reserve (e.targets.size ());
                              for (const auto &target : e.targets)
                                {
                                  failedDestinations.push_back (target.dest);
                                }

                              m_routingControlFailureCb (
                                failedDestinations,
                                routingSequence,
                                operation,
                                routingSection,
                                routingTotalSections,
                                true);
                            }
                        }
                    }
                }
            }

          // Do not call the generic link-failure callback here.  OPNET sends
          // routing completion through br_Sent_Info/routesHopSecSentPacket(),
          // and the callback above is its equivalent.  Calling
          // m_linkFailureCb(e.dest) as well incorrectly penalizes DATA loss
          // and, for a grouped routing frame, can penalize the primary target
          // even after that target already ACKed.

          const DataAdmissionSnapshot timeoutBefore =
            GetDataAdmissionSnapshot (e.dest);
          const uint32_t timeoutResendQueueBefore =
            static_cast<uint32_t> (m_resendQueue.size ());
          CsrDifferentialAppTag timeoutAppTag;
          const bool timeoutAppSequenceValid =
            e.frame->PeekPacketTag (timeoutAppTag);

          // Inform Net layer that this flow lost a packet
          NotifyNsdpFromEntry (e);

          if (e.flowControlTracked)
            {
              FlowCtrlEntry &fc =
                GetFlowCtrlEntry (
                  e.dest);

              if (fc.outstanding > 0)
                {
                  fc.outstanding--;

                  if (m_pendingDataCount > 0)
                    {
                      m_pendingDataCount--;
                    }

                  std::cout << "[HOP " << m_nodeId
                            << "] Pending DATA decrement"
                            << " reason=no-ACK"
                            << " neighbor="
                            << e.dest
                            << " pending="
                            << m_pendingDataCount
                            << std::endl;
                }

              fc.consecutiveCleanAcks = 0;

              if (fc.threshold > 0)
                {
                  uint32_t oldThreshold =
                    fc.threshold;

                  fc.threshold--;

                  std::cout
                    << "[HOP " << m_nodeId
                    << "] Adaptive flow threshold decreased"
                    << " neighbor="
                    << e.dest
                    << " old="
                    << oldThreshold
                    << " new="
                    << fc.threshold
                    << " effectiveWindow="
                    << (fc.threshold + 1)
                    << " reason=no-ACK"
                    << std::endl;
                }
            }

          if (IsDifferentialAdmissionTraceEnabled () &&
              e.flowControlTracked &&
              e.networkFlowMetadataValid)
            {
              const DataAdmissionSnapshot timeoutAfter =
                GetDataAdmissionSnapshot (e.dest);
              CsrDifferentialTraceEvent completionEvent;
              completionEvent.event = "hop_completion";
              completionEvent.node = CsrTraceInteger (m_nodeId);
              completionEvent.peer = CsrTraceInteger (e.dest);
              completionEvent.packetType = "data";
              completionEvent.source = CsrTraceInteger (e.networkSource);
              completionEvent.destination =
                CsrTraceInteger (e.networkDestination);
              if (timeoutAppSequenceValid)
                {
                  completionEvent.sequence =
                    CsrTraceInteger (timeoutAppTag.GetSequence ());
                }
              completionEvent.success = "0";
              completionEvent.reason = "no_ack";
              completionEvent.nextHop = CsrTraceInteger (e.dest);
              completionEvent.detail =
                "hop_sequence=" + CsrTraceInteger (e.seq) +
                ";resend_count=" + CsrTraceInteger (e.resendCount) +
                ";pending_before=" +
                  CsrTraceInteger (timeoutBefore.pendingData) +
                ";pending_after=" +
                  CsrTraceInteger (timeoutAfter.pendingData) +
                ";pending_limit=" +
                  CsrTraceInteger (timeoutAfter.pendingThreshold) +
                ";outstanding_before=" +
                  CsrTraceInteger (timeoutBefore.neighborOutstanding) +
                ";outstanding_after=" +
                  CsrTraceInteger (timeoutAfter.neighborOutstanding) +
                ";threshold_before=" +
                  CsrTraceInteger (timeoutBefore.neighborThreshold) +
                ";threshold_after=" +
                  CsrTraceInteger (timeoutAfter.neighborThreshold) +
                ";resend_queue_before=" +
                  CsrTraceInteger (timeoutResendQueueBefore) +
                ";resend_queue_after=" +
                  CsrTraceInteger (timeoutResendQueueBefore - 1) +
                ";nsdp_released=1;capacity_released=1";
              WriteDifferentialAdmissionTrace (completionEvent);
            }

          it = m_resendQueue.erase (it);
          WriteDifferentialStatisticSample (
            m_nodeId,
            CSR_STAT_HOP_RESEND_QUEUE_SIZE,
            static_cast<double> (m_resendQueue.size ()));
          // Source check_resend() requests a Network queue scan after every
          // final expiry, even when the frame has no NSDP or routing metadata.
          ScheduleNwkQueueWake ();
          continue;
        }

      ++it;
    }

native_retry_copy.text:
// Source check_resend() completes its full deletion pass before beginning
// the retransmission pass.  Preserve that same-time ordering so released
// capacity and timeout callbacks precede any newly queued resend.
for (auto &e : m_resendQueue)
  {
    if (!e.initialTxConfirmed ||
        e.resendCount >= m_maxNumResend ||
        now - e.lastTxTime < m_resendTime)
      {
        continue;
      }

    NS_LOG_INFO ("Hop " << m_nodeId << " resending dest="
                        << e.dest << " seq=" << e.seq
                        << " dscp=" << unsigned (e.dscp)
                        << " attempt=" << (e.resendCount + 1));

    e.resendCount++;

    // Keep the legacy provisional timestamp.  br_hop records the time it
    // hands a retransmission to MAC, then br_Mac_Hop_Inst replaces it with
    // the actual sent time when transmission occurs.
    e.lastTxTime = now;

    m_mac->EnqueueTxFrame (e.frame->Copy (), e.dest,
                           e.dscp, /*ackable*/ true);
  }

native_sent_without_owner.text:
void NotifyMacFrameSent (
  CsrNodeId dest,
  uint16_t seq,
  Time sentAt)
{
  ResendEntry *entry =
    FindResendEntry (dest, seq);

  if (entry == nullptr)
    {
      // br_hop retains one handle to the most recently scheduled resend
      // timer.  A MAC sent indication without a matching resend entry still
      // installs the fallback global scan when that handle is no longer
      // pending (notably after resend-queue overflow).
      if (!m_lastResendTimerEvent.IsPending ())
        {
          Time due = sentAt + m_resendTime + CsrOpnetTic ();
          Time delay =
            due > Simulator::Now ()
              ? due - Simulator::Now ()
              : Seconds (0.0);
          m_lastResendTimerEvent =
            Simulator::Schedule (
              delay,
              &CsrHopLayer::CheckResend,
              this);
        }
      return;
    }

  entry->lastTxTime = sentAt;
  entry->initialTxConfirmed = true;

native_nsdp_callback.text:
void NotifyNsdpFromEntry (const ResendEntry &entry)
{
  if (m_nsdpDecrCb.IsNull ())
    {
      return;
    }

  if (!entry.networkFlowMetadataValid)
    {
      return;
    }

  m_nsdpDecrCb (entry.networkSource, entry.networkDestination);
}

